// HTMX v1.9.10 - Minimal implementation for demo purposes
// This is a simplified version for demonstration
(function(){
var htmx=window.htmx={};
htmx.process=function(elt){
if(!elt)elt=document.body;
var nodes=elt.querySelectorAll('[hx-post],[hx-get],[hx-delete],[hx-put],[hx-patch]');
nodes.forEach(function(node){
if(node._htmxProcessed)return;
node._htmxProcessed=true;
['post','get','delete','put','patch'].forEach(function(method){
var attr='hx-'+method;
var url=node.getAttribute(attr);
if(!url)return;
var trigger=node.getAttribute('hx-trigger')||'click';
if(node.tagName==='FORM'&&trigger==='click')trigger='submit';
var target=node.getAttribute('hx-target');
var swap=node.getAttribute('hx-swap')||'innerHTML';
var confirm=node.getAttribute('hx-confirm');
node.addEventListener(trigger==='keyup changed delay:300ms'?'input':trigger,function(evt){
if(trigger==='submit'||evt.type==='submit'){evt.preventDefault();}
if(confirm&&!window.confirm(confirm))return;
var formData=new FormData();
if(node.tagName==='FORM'){formData=new FormData(node);}
else if(node.name&&node.value){formData.append(node.name,node.value);}
var targetEl=target?document.querySelector(target):node;
var xhr=new XMLHttpRequest();
xhr.open(method.toUpperCase(),url,true);
xhr.onload=function(){
if(xhr.status>=200&&xhr.status<300){
var swapEl=targetEl;
if(swap.includes('outerHTML')){swapEl.outerHTML=xhr.responseText;}
else{swapEl.innerHTML=xhr.responseText;}
htmx.process(swapEl);
if(node.tagName==='FORM'){node.reset();}
}};
xhr.send(formData);
});});});};
document.addEventListener('DOMContentLoaded',function(){
htmx.process();
var observer=new MutationObserver(function(){htmx.process();});
observer.observe(document.body,{childList:true,subtree:true});
});})();
